import{_ as l,r as s,o as i,c as d,a as o,b as e,d as r,e as n}from"./chunks/framework.8NMv9ABN.js";const k=JSON.parse('{"title":"Monitor","description":"","frontmatter":{},"headers":[],"relativePath":"uk/tools/monitor.md","filePath":"uk/tools/monitor.md"}'),h={name:"uk/tools/monitor.md"};function c(g,t,u,m,p,b){const a=s("Screenshot");return i(),d("div",null,[t[0]||(t[0]=o("h1",{id:"monitor",tabindex:"-1"},[e("Monitor "),o("a",{class:"header-anchor",href:"#monitor","aria-label":'Permalink to "Monitor"'},"​")],-1)),t[1]||(t[1]=o("p",null,[e("Monitor ранжує весь ринок за метрикою волатильності й тримає верхівку цього рейтингу на екрані. Якщо "),o("a",{href:"/manual/uk/tools/knives.html"},"Knives"),e(" чекає, поки щось перетне межу, і тоді повідомляє, то Monitor — це безперервно відсортована таблиця лідерів.")],-1)),t[2]||(t[2]=o("p",null,[e("Усі показники рахуються за "),o("strong",null,"5-хвилинними свічками"),e(".")],-1)),r(a,{src:"monitor",alt:"Вікно Monitor із ранжованими картками тікерів",caption:"Вікно Monitor"}),t[3]||(t[3]=n('<h2 id="як-читати-вікно" tabindex="-1">Як читати вікно <a class="header-anchor" href="#як-читати-вікно" aria-label="Permalink to &quot;Як читати вікно&quot;">​</a></h2><h3 id="заголовок-вікна" tabindex="-1">Заголовок вікна <a class="header-anchor" href="#заголовок-вікна" aria-label="Permalink to &quot;Заголовок вікна&quot;">​</a></h3><p>Заголовок — це живе зведення чинних наразі налаштувань:</p><ul><li><strong>5m</strong> — таймфрейм свічок. Незмінний.</li><li><strong>NATR | Vol | Chg</strong> — активне сортування. Це кнопки: клацніть, щоб пересортувати, не відкриваючи налаштувань.</li><li><strong>Деталі сортування</strong> — що саме робить поточне сортування. Для NATR показує метод згладжування й режим агрегації (напр. <code>SMA · Weighted</code>); для Volume — джерело й тип (напр. <code>Total · 75m</code>); для % Change — просто <code>% Change</code>. Якщо діє фільтр мінімального обсягу, до цього додається <code>min $&lt;сума&gt;</code>.</li><li><strong>Пороги сповіщень</strong> — <code>NATR ≥x% · % ≥y%</code>. Приглушені, коли звук сповіщень вимкнено.</li><li><strong>Іконки бірж</strong> — увімкнені біржі в порядку пріоритету.</li><li><strong>Disconnected</strong> — показується, якщо зв&#39;язок із даними обірвався.</li></ul><h3 id="картка-тікера" tabindex="-1">Картка тікера <a class="header-anchor" href="#картка-тікера" aria-label="Permalink to &quot;Картка тікера&quot;">​</a></h3><p>Кожна картка показує тікер, біржі, де він торгується, і три метрики:</p><table tabindex="0"><thead><tr><th>Метрика</th><th>Значення</th></tr></thead><tbody><tr><td><strong>NATR</strong></td><td>Волатильність — нормалізований середній істинний діапазон, на 5хв свічках</td></tr><tr><td><strong>Volume</strong></td><td>Обсяг торгів у доларах за вікно, задане в <a href="#volume-type">Volume type</a></td></tr><tr><td><strong>% Change</strong></td><td>Зміна ціни за 5 хвилин</td></tr></tbody></table><p>Наведення на логотип біржі показує <code>Listed on &lt;біржа&gt;</code>. Картки мають кнопку розгортання, яка відкриває повноекранний графік із тими самими інструментами рисування, що й <a href="/manual/uk/tools/analyzer.html#інструменти-рисування">Analyzer</a>.</p><h3 id="що-означають-кольори" tabindex="-1">Що означають кольори <a class="header-anchor" href="#що-означають-кольори" aria-label="Permalink to &quot;Що означають кольори&quot;">​</a></h3><p>Забарвлення керується правилами <a href="#metric-colors">кольорів метрик</a>, які не пов&#39;язані з порогами сповіщень:</p><ul><li><strong>NATR</strong> переходить від кольору рівня 1 до кольору рівня 2, коли волатильність проходить кожен рівень.</li><li><strong>% Change</strong> забарвлюється за напрямом — одна пара кольорів для зростання, інша для падіння — і так само підвищується на рівні 2.</li></ul><p>Якщо динамічні кольори для метрики вимкнено, вона натомість просто підсвічується при перетині свого <strong>порогу сповіщення</strong>.</p><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2><p>Відкрийте вкладку <strong>Monitor</strong> у головному вікні.</p>',14)),r(a,{src:"monitor-settings",alt:"Налаштування сортування Monitor",caption:"Налаштування Monitor — сортування"}),t[4]||(t[4]=n('<h3 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h3><h4 id="sort-by" tabindex="-1">Sort by <a class="header-anchor" href="#sort-by" aria-label="Permalink to &quot;Sort by&quot;">​</a></h4><p>Яка метрика ранжує список: <strong>NATR</strong>, <strong>Volume</strong> або <strong>% Change</strong>. За замовчуванням NATR.</p><h4 id="natr-method" tabindex="-1">NATR method <a class="header-anchor" href="#natr-method" aria-label="Permalink to &quot;NATR method&quot;">​</a></h4><p>Алгоритм згладжування для розрахунку NATR. За замовчуванням <strong>SMA</strong>.</p><ul><li><strong>RMA</strong> — ковзне середнє Вайлдера. Гладше, повільніше реагує.</li><li><strong>SMA</strong> — просте ковзне середнє. Чутливіше до недавніх свічок.</li></ul><h4 id="natr-aggregation" tabindex="-1">NATR aggregation <a class="header-anchor" href="#natr-aggregation" aria-label="Permalink to &quot;NATR aggregation&quot;">​</a></h4><p>Як формується одне значення NATR для тікера, що торгується на кількох біржах. За замовчуванням <strong>Weighted</strong>.</p><ul><li><strong>Weighted</strong> — середньозважене за обсягом по біржах.</li><li><strong>Highest</strong> — максимальний NATR серед усіх бірж.</li><li><strong>Priority</strong> — значення з першої біржі у вашому порядку пріоритету, яка має дані для цього тікера.</li></ul><h4 id="volume-source" tabindex="-1">Volume source <a class="header-anchor" href="#volume-source" aria-label="Permalink to &quot;Volume source&quot;">​</a></h4><p>Звідки береться значення обсягу. За замовчуванням <strong>Total</strong>.</p><ul><li><strong>Total</strong> — оборот, підсумований по всіх увімкнених біржах.</li><li><strong>Priority</strong> — оборот лише з першої біржі в порядку пріоритету.</li></ul><h4 id="volume-type" tabindex="-1">Volume type <a class="header-anchor" href="#volume-type" aria-label="Permalink to &quot;Volume type&quot;">​</a></h4><p>Яке вікно охоплює значення обсягу. За замовчуванням <strong>75m</strong>.</p><ul><li><strong>75m</strong> — ковзний обсяг за 75 хвилин.</li><li><strong>5m</strong> — обсяг поточної 5-хвилинної свічки.</li></ul><div class="warning custom-block"><p class="custom-block-title">Це налаштування також обирає, який фільтр обсягу є чинним</p><p>Monitor має два повзунки мінімального обсягу, і <strong>працює лише той, що відповідає поточному Volume type</strong>:</p><ul><li>Volume type <strong>75m</strong> → список фільтрує повзунок <strong>Min volume (75m)</strong>.</li><li>Volume type <strong>5m</strong> → список фільтрує повзунок <strong>Min volume (5m)</strong>.</li></ul><p>Другий повзунок зберігає своє значення, але не діє. Якщо ви виставили фільтр і не бачите результату — перевірте, чи Volume type відповідає тому повзунку, який ви рухали. Напис <code>min $…</code> у заголовку завжди показує той, що діє насправді.</p></div><h4 id="min-volume-75m" tabindex="-1">Min volume (75m) <a class="header-anchor" href="#min-volume-75m" aria-label="Permalink to &quot;Min volume (75m)&quot;">​</a></h4><p>Виключає тікери з обсягом за 75 хвилин нижче цього значення. Діапазон <strong>від $0 до $100M</strong> з кроком $1M, за замовчуванням 0 — показується як <code>None</code>, тобто без фільтрації.</p><h4 id="min-volume-5m" tabindex="-1">Min volume (5m) <a class="header-anchor" href="#min-volume-5m" aria-label="Permalink to &quot;Min volume (5m)&quot;">​</a></h4><p>Виключає тікери з обсягом поточної 5-хвилинної свічки нижче цього значення. Діапазон <strong>від $0 до $10M</strong> з кроком $100K, за замовчуванням 0 (<code>None</code>).</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-cards" tabindex="-1">Max cards <a class="header-anchor" href="#max-cards" aria-label="Permalink to &quot;Max cards&quot;">​</a></h4><p>Скільки карток тікерів показувати. Діапазон <strong>від 3 до 30</strong>, за замовчуванням 12. Список переранжовується наживо при зміні.</p><h3 id="metric-colors" tabindex="-1">Metric colors <a class="header-anchor" href="#metric-colors" aria-label="Permalink to &quot;Metric colors&quot;">​</a></h3><p>Дві метрики мають налаштовувані динамічні кольори: <strong>NATR</strong> і <strong>% Change</strong>. Кожна має головний перемикач, два пороги та кольори для тексту, контуру й фону.</p><h4 id="natr-color" tabindex="-1">NATR color <a class="header-anchor" href="#natr-color" aria-label="Permalink to &quot;NATR color&quot;">​</a></h4><p>Головний перемикач динамічного забарвлення NATR. За замовчуванням увімкнено. Вимкнено — NATR натомість просто підсвічується при перетині порогу сповіщення.</p><table tabindex="0"><thead><tr><th>Налаштування</th><th>Що робить</th><th>Діапазон</th><th>За замовчуванням</th></tr></thead><tbody><tr><td><strong>Level 1 threshold</strong></td><td>NATR вище цього використовує колір 1</td><td>1–10%, крок 0.5</td><td>3% (<code>#A082E8</code>)</td></tr><tr><td><strong>Level 2 threshold</strong></td><td>NATR вище цього використовує колір 2</td><td>1.5–10%, крок 0.5</td><td>фактично 7% (<code>#FFA040</code>)</td></tr><tr><td><strong>Outline</strong></td><td>Колір рамки для кожного рівня плюс перемикач</td><td>—</td><td>вимкнено</td></tr><tr><td><strong>Background</strong></td><td>Колір заливки для кожного рівня плюс перемикач</td><td>—</td><td>вимкнено</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Рівень 2 додається до рівня 1</p><p>Значення поруч із повзунком Level 2 — це <strong>Level 1 + Level 2</strong>, а не власне значення повзунка. При Level 1 на 3% і повзунку Level 2 на 4% напис показує <strong>7.0%</strong> — саме там насправді починається колір 2.</p><p>Те саме стосується повзунка Level 2 для % Change. Читайте напис, а не повзунок.</p></div><p>Outline і Background — окремі перемикачі з власними кольорами рівнів 1 і 2, тож можна мати лише кольоровий текст, кольорову рамку, залиту картку або будь-яку комбінацію.</p><div class="tip custom-block"><p class="custom-block-title">Кожен із цих кольорів може бути напівпрозорим</p><p>Усі чотирнадцять слотів кольору тут використовують ту саму палітру, що й решта застосунку, а в ній є повзунок непрозорості. Непрозорість зберігається всередині hex, тож напівпрозоре значення має 8 символів (<code>#rrggbbaa</code>), а не 6 — див. <a href="/manual/uk/customize/chart-colors.html#палітра">палітру</a>.</p><p>Найбільше це важить для заливок фону: при повній непрозорості залита картка перекриває рядок під собою, а десь на 15–25% лише підфарбовує його.</p></div><h4 id="change-direction" tabindex="-1">% Change direction <a class="header-anchor" href="#change-direction" aria-label="Permalink to &quot;% Change direction&quot;">​</a></h4><p>Головний перемикач динамічного забарвлення % Change. За замовчуванням увімкнено.</p><p>Працює як NATR, але з <strong>двома кольорами на рівень</strong> — один для зростання, інший для падіння:</p><table tabindex="0"><thead><tr><th>Налаштування</th><th>Діапазон</th><th>За замовчуванням</th></tr></thead><tbody><tr><td><strong>Level 1 threshold</strong></td><td>1–10%, крок 0.5</td><td>2% — зростання <code>#4CAF50</code>, падіння <code>#E05555</code></td></tr><tr><td><strong>Level 2 threshold</strong></td><td>1.5–10%, крок 0.5</td><td>фактично 5% — зростання <code>#00E676</code>, падіння <code>#FF5252</code></td></tr><tr><td><strong>Outline</strong></td><td>—</td><td>вимкнено</td></tr><tr><td><strong>Background</strong></td><td>—</td><td>вимкнено</td></tr></tbody></table><h3 id="іконки-бірж" tabindex="-1">Іконки бірж <a class="header-anchor" href="#іконки-бірж" aria-label="Permalink to &quot;Іконки бірж&quot;">​</a></h3><h4 id="show-icons" tabindex="-1">Show icons <a class="header-anchor" href="#show-icons" aria-label="Permalink to &quot;Show icons&quot;">​</a></h4><p>Показує або приховує логотипи бірж на картках тікерів. За замовчуванням увімкнено.</p><h3 id="exchanges" tabindex="-1">Exchanges <a class="header-anchor" href="#exchanges" aria-label="Permalink to &quot;Exchanges&quot;">​</a></h3><p>Один список із перетягуванням відповідає і за пріоритет, і за увімкнення, розділений лінією:</p><ul><li><strong>Вище розділювача</strong> — увімкнені, пронумеровані за рангом. Ранг важливий для варіантів <code>Priority</code> у NATR aggregation і Volume source.</li><li><strong>Нижче розділювача</strong> — вимкнені. Їхній ранг показано як <code>—</code>, і вони не дають жодних даних.</li></ul><p>Перетягніть біржу через розділювач, щоб увімкнути або вимкнути її. Усі п&#39;ять за замовчуванням увімкнені, у порядку <strong>Binance, Bybit, OKX, Gate.io, Hyperliquid</strong>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Типовий порядок пріоритету в Monitor відрізняється від Knives (<code>Bybit, Binance, Gate.io, OKX, Hyperliquid</code>). Ці два інструменти мають окремі списки пріоритету — зміна порядку в одному не впливає на інший.</p></div><h3 id="alerts" tabindex="-1">Alerts <a class="header-anchor" href="#alerts" aria-label="Permalink to &quot;Alerts&quot;">​</a></h3><h4 id="alert-sound" tabindex="-1">Alert sound <a class="header-anchor" href="#alert-sound" aria-label="Permalink to &quot;Alert sound&quot;">​</a></h4><p>Відтворює звук, коли тікер досягає порогу NATR або % Change нижче. За замовчуванням увімкнено. Коли вимкнено, напис порогів у заголовку приглушено.</p><h4 id="natr-threshold" tabindex="-1">NATR threshold <a class="header-anchor" href="#natr-threshold" aria-label="Permalink to &quot;NATR threshold&quot;">​</a></h4><p>Підсвічує й сповіщає, коли NATR перевищує цей відсоток. Діапазон <strong>від 3% до 20%</strong> з кроком 0.5%, за замовчуванням 5%.</p><h4 id="change-threshold" tabindex="-1">% Change threshold <a class="header-anchor" href="#change-threshold" aria-label="Permalink to &quot;% Change threshold&quot;">​</a></h4><p>Підсвічує й сповіщає, коли % зміни перевищує це значення. Діапазон <strong>від 3% до 20%</strong> з кроком 0.5%, за замовчуванням 4%.</p><div class="info custom-block"><p class="custom-block-title">Пороги й кольори — це дві різні системи</p><p>Пороги сповіщень тут вирішують, коли спрацює <em>звук</em>. Рівні <a href="#metric-colors">кольорів метрик</a> вирішують, як значення <em>намальовано</em>. Вони налаштовуються незалежно й можуть мати різні значення — картка може бути забарвлена, не спричинивши звуку, і навпаки.</p></div><h2 id="пов-язане" tabindex="-1">Пов&#39;язане <a class="header-anchor" href="#пов-язане" aria-label="Permalink to &quot;Пов&#39;язане&quot;">​</a></h2><ul><li><a href="/manual/uk/tools/knives.html">Knives</a> — стрічка спрацювань замість рейтингу</li><li><a href="/manual/uk/tools/analyzer.html">Analyzer</a> — повноцінний простір для графіків</li><li><a href="/manual/uk/customize/chart-colors.html">Графіки та рисування</a> — кольори свічок, які використовують графіки Monitor</li></ul>',53))])}const f=l(h,[["render",c]]);export{k as __pageData,f as default};
